import{_ as r,o as t,c as o,a2 as e}from"./chunks/framework.BV21bweQ.js";const g=JSON.parse('{"title":"鹿族","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/鹿族.md","filePath":"表层/种族/鹿族.md","lastUpdated":1787066340000}'),l={name:"表层/种族/鹿族.md"};function i(n,a,s,h,d,u){return t(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="鹿族" tabindex="-1">鹿族 <a class="header-anchor" href="#鹿族" aria-label="Permalink to &quot;鹿族&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>鹿族是五大主族之一，共同体时期承担科研相关的一切，以<strong>好奇心与求知欲</strong>为种族核心特质。黑暗时代中，鹿族沦为法师的助手/宠物。黑暗时代结束后，鹿族重新崛起为<strong>世界一极</strong>，拥有全大陆最先进的科技水平，是当前大陆政治格局的核心力量之一。</p><hr><h2 id="体貌特征" tabindex="-1">体貌特征 <a class="header-anchor" href="#体貌特征" aria-label="Permalink to &quot;体貌特征&quot;">​</a></h2><ul><li><strong>形态</strong>：直立行走，具有鹿类动物的典型福瑞形态。</li><li><strong>体型</strong>：普遍修长优雅，动作敏捷。</li><li><strong>毛色</strong>：以棕色、黄褐色为主，部分个体有白色斑点。</li><li><strong>鹿角</strong>：雄性有明显的鹿角，雌性鹿角较小或无角。</li></ul><hr><h2 id="种族特质" tabindex="-1">种族特质 <a class="header-anchor" href="#种族特质" aria-label="Permalink to &quot;种族特质&quot;">​</a></h2><h3 id="核心特质-好奇心与求知欲" tabindex="-1">核心特质：好奇心与求知欲 <a class="header-anchor" href="#核心特质-好奇心与求知欲" aria-label="Permalink to &quot;核心特质：好奇心与求知欲&quot;">​</a></h3><ul><li><strong>探索精神</strong>：天生渴望探索未知、理解世界运行规律。</li><li><strong>研究倾向</strong>：对科学、技术与自然现象有天然的求知欲。</li><li><strong>创新驱动</strong>：追求创新与技术突破，不满足于现有知识边界。</li><li><strong>理性</strong>：倾向于理性思考与逻辑分析。</li></ul><hr><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><h3 id="共同体时期-科研担当" tabindex="-1">共同体时期：科研担当 <a class="header-anchor" href="#共同体时期-科研担当" aria-label="Permalink to &quot;共同体时期：科研担当&quot;">​</a></h3><p>在五大主族分工的共同体体系中，鹿族承担<strong>科研相关的一切</strong>，在神明的点拨下推动了一系列技术突破：</p><ul><li><strong>建国 50 年</strong>：蒸汽机车成功运行，奠定交通与工业基础。</li><li><strong>建国 100 周年</strong>：电灯问世，电子技术突破。</li><li><strong>建国 120 年</strong>：神明递给鹿族学者一枚二极管，解锁电子技术大门，此后无线电、电报等现代通讯技术迅速爆发。</li></ul><p>蒸汽机车、电灯、电子技术等成就，成为鹿族代代相传的民族记忆。共同体末期，鹿族曾主导&quot;神明复活计划&quot;，实验发生严重事故，鹿族因事故责任失去独裁能力。</p><h3 id="黑暗时代-法师的助手-宠物" tabindex="-1">黑暗时代：法师的助手/宠物 <a class="header-anchor" href="#黑暗时代-法师的助手-宠物" aria-label="Permalink to &quot;黑暗时代：法师的助手/宠物&quot;">​</a></h3><p>黑暗时代开始后，鹿族逐渐成为新五族法师的<strong>助手/宠物</strong>，其知识能力被法师阶层利用。这段时期的真实经历长期不为外界所知。</p><hr><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><h3 id="鹿国-世界一极" tabindex="-1">鹿国：世界一极 <a class="header-anchor" href="#鹿国-世界一极" aria-label="Permalink to &quot;鹿国：世界一极&quot;">​</a></h3><p>黑暗时代结束后，鹿族建立独立国家——<strong>鹿国</strong>：</p><ul><li><strong>科技水平</strong>：拥有全大陆最先进的科研水平与技术储备。</li><li><strong>国家体制</strong>：相对<strong>分散</strong>，学术氛围浓厚，各研究机构、地方势力拥有较大自主权，类似联邦或邦联制。这既是其创新活力的来源，也是其决策效率低下的根源。</li><li><strong>战略姿态</strong>：在冷战中采取&quot;守势&quot;战略，不愿轻易开战。</li></ul><h3 id="法师军团" tabindex="-1">法师军团 <a class="header-anchor" href="#法师军团" aria-label="Permalink to &quot;法师军团&quot;">​</a></h3><p>鹿国是大陆已知<strong>唯一拥有系统化、成建制法师力量</strong>的政权。法师数量稀少，被作为高精尖的战略威慑使用，是鹿国对抗熊国庞大常规军力的关键。</p><h3 id="厌战思潮与狮族战争记忆" tabindex="-1">厌战思潮与狮族战争记忆 <a class="header-anchor" href="#厌战思潮与狮族战争记忆" aria-label="Permalink to &quot;厌战思潮与狮族战争记忆&quot;">​</a></h3><p>狮族战争是鹿族在黑暗时代后伤亡最惨重的一次战争——鹿族在绞肉战中损失大量法师与陆军精锐。战争的惨痛记忆直接催生了鹿族国内<strong>普遍的厌战思潮</strong>，也使民众不信任强集权政府，促成了鹿国松散、个体独立的国家体制。</p><h3 id="环形山计划" tabindex="-1">&quot;环形山计划&quot; <a class="header-anchor" href="#环形山计划" aria-label="Permalink to &quot;&quot;环形山计划&quot;&quot;">​</a></h3><p>鹿族曾以大陆上随处可见的环形山地貌为代号设立核武器研发项目，对外伪装为&quot;地质地貌研究项目&quot;。核弹试爆成功后，爆心原地形成了一座与大陆上古环形山相似的全新环形山，原本的掩饰名称成为现实的毁灭痕迹。此后鹿族将核武器作为冷战中的战略威慑筹码，始终不敢轻易使用。</p><h3 id="与熊国的冷战" tabindex="-1">与熊国的冷战 <a class="header-anchor" href="#与熊国的冷战" aria-label="Permalink to &quot;与熊国的冷战&quot;">​</a></h3><p>鹿国与熊国为当前世界的两极，处于冷战对峙之中。双方矛盾的根源在于<strong>故土的双重宣称</strong>：熊族宣称其故土在黑暗时代被鹿族等族群占据，鹿族则经数百年经营已将此地视为本族的实际故土。详见 <a href="./熊族">熊族</a>。</p><hr><h2 id="深层真相" tabindex="-1">深层真相 <a class="header-anchor" href="#深层真相" aria-label="Permalink to &quot;深层真相&quot;">​</a></h2><blockquote><p>鹿族在黑暗时代暗中崛起的具体经过不属表层认知。</p></blockquote><ul><li><a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./五大主族总览">五大主族总览</a></li><li><a href="./熊族">熊族</a></li><li><a href="./../历史/共同体时期">共同体时期</a></li><li><a href="./../历史/黑暗时代">黑暗时代</a></li><li><a href="./../历史/当前时代">当前时代</a></li></ul><hr>',38)])])}const q=r(l,[["render",i]]);export{g as __pageData,q as default};
